}

function tokens(text) {
  const stop = new Set(['that','this','with','from','have','your','will','would','should','could','there','their','about','based','using','because','then','than','into','only','also','when','where','what','which','been','being']);
  return String(text || '').toLowerCase().split(/[^a-z0-9$]+/).filter((t) => t.length > 3 && !stop.has(t));
}

function evidenceScore(sentence, nodes) {
  const terms = tokens(sentence);
